#include <memory>
#include <iostream>

void transfer_test() {
    std::auto_ptr<int> p1(new int(42));
    std::cout << "P1 before copy: " << *p1 << std::endl;

    // Ownership transfer (destructive copy)
    std::auto_ptr<int> p2 = p1;

    // P1 is now nullified
    if (p1.get() == nullptr) {
        std::cout << "P1 is null after copy.\n";
    }
    std::cout << "P2 owns: " << *p2 << std::endl;

    // Attempting to use *p1 here is UB/crash
}
